web.css:
html {
	background: #0B0E1A;
}
body::before {
	content: "";
	position: fixed;
	inset: 0;
	z-index: 1;
	pointer-events: none;
	background: linear-gradient(115deg, rgba(181, 126, 220, 0.35) 0%, rgba(79, 195, 247, 0.28) 40%, rgba(67, 170, 139, 0.28) 70%, rgba(181, 126, 220, 0.35) 100%);
	background-size: 320% 320%;
	mix-blend-mode: screen;
	opacity: 0.6;
	animation: aurora-drift 16s ease-in-out infinite;
}
body::after {
	content: "";
	position: fixed;
	top: -15vmax;
	left: -15vmax;
	width: 55vmax;
	height: 55vmax;
	z-index: 1;
	pointer-events: none;
	border-radius: 50%;
	background: radial-gradient(circle, rgba(181, 126, 220, 0.55) 0%, rgba(79, 195, 247, 0.3) 45%, transparent 70%);
	filter: blur(60px);
	mix-blend-mode: screen;
	animation: aurora-blob 20s ease-in-out infinite alternate;
}
@keyframes aurora-drift {
	0%, 100% { background-position: 0% 30%; }
	50% { background-position: 100% 70%; }
}
@keyframes aurora-blob {
	0% { transform: translate(0, 0) scale(1); }
	50% { transform: translate(55vw, 30vh) scale(1.3); }
	100% { transform: translate(85vw, 5vh) scale(0.85); }
}
